// Pack remuxes one item's original file into fMP4-HLS (the D-3 pack lane) and
// publishes the result atomically under a fresh build-nonce directory (D-5):
// stream copy only — `-c copy -map 0:v:0 -map 0:a -sn -dn`, one video stream
// and every audio track, subtitles and data streams dropped; no decode and no
// encode, ever. Head-first (D-4): the first HeadChunk seconds are published
// playable (EVENT playlist, no ENDLIST) before the remainder packages; on
// completion the playlist is rewritten atomically (aside, then rename) to the
// grown, ENDLIST-terminated build. Playlists are byte-identical for a given
// published build. The single ffmpeg exec site of the whole system is
// runFFmpeg below — arg-slice only, never a shell.
//
// ffprobe carries the stored facts for one decision only: when the probed
// duration is at most HeadChunk the whole file IS the head chunk, so the tail
// phase is skipped (a seek past EOF would mint a junk fragment). Absent facts
// simply run both phases. A cancelled context (or any ffmpeg failure) is an
// error; partial directories are cleaned up and nothing is returned, so the
// caller persists no pointer.
func (s *Service) Pack(ctx context.Context, itemID, absPath string, ffprobe map[string]any) (Build, error) {
	s.normalize()
	if s.Secret == nil {
		return Build{}, errors.New("stream: service has no token secret")
	}
	if err := ctx.Err(); err != nil {
		return Build{}, err
	}
	if absPath == "" {
		return Build{}, errors.New("stream: pack needs the original's absolute path")
	}
	if err := s.ensureRoot(); err != nil {
		return Build{}, fmt.Errorf("stream: create artifact root: %w", err)
	}
	nonce, err := newNonce()
	if err != nil {
		return Build{}, fmt.Errorf("stream: nonce: %w", err)
	}
	final, err := s.buildDir(itemID, nonce)
	if err != nil {
		return Build{}, err
	}
	tmp := filepath.Join(s.Root, itemID, ".tmp-"+nonce)

	if err := s.packInto(ctx, itemID, nonce, absPath, ffprobe, tmp, final); err != nil {
		os.RemoveAll(tmp) // best-effort cleanup; nothing is referenced yet
		os.RemoveAll(final)
		return Build{}, err
	}
	os.RemoveAll(tmp)
	return Build{
		Playlist: mediaPrefix + "/" + itemID + "/" + nonce + "/index.m3u8",
		Nonce:    nonce,
	}, nil
}

// packInto runs the head phase into tmp, publishes it to final (the D-4
// head-first publish point), then — unless the file already fits in the head
// chunk — runs the tail phase and rewrites the playlist to the complete,
// ENDLIST-terminated merge.
func (s *Service) packInto(ctx context.Context, itemID, nonce, absPath string, ffprobe map[string]any, tmp, final string) error {
	if err := os.MkdirAll(tmp, 0o755); err != nil {
		return fmt.Errorf("stream: create build dir: %w", err)
	}
	if err := s.runFFmpeg(ctx, packHeadArgs(absPath, s.HeadChunk, s.SegmentTime, tmp)); err != nil {
		return err
	}
	headPlaylist, err := os.ReadFile(filepath.Join(tmp, "index.m3u8"))
	if err != nil {
		return fmt.Errorf("stream: head playlist: %w", err)
	}
	if s.afterHead != nil {
		s.afterHead(filepath.Join(tmp, "index.m3u8"))
	}

	dur := probeSeconds(ffprobe)
	if dur > 0 && dur <= s.HeadChunk.Seconds() {
		// The whole file is the head chunk: finalize the head playlist and
		// publish the build. This is the ONLY playlist write that is not a
		// merge (still atomic, still into final).
		return writeAtomic(final, filepath.Join(final, "index.m3u8"), finalizeHead(headPlaylist))
	}

	if err := os.Rename(tmp, final); err != nil { // atomic publish of the partial build
		return fmt.Errorf("stream: publish head: %w", err)
	}
	tailTmp := filepath.Join(s.Root, itemID, ".tmp-tail-"+nonce)
	if err := os.MkdirAll(tailTmp, 0o755); err != nil {
		return fmt.Errorf("stream: create tail dir: %w", err)
	}
	if err := s.runFFmpeg(ctx, packTailArgs(absPath, s.HeadChunk, s.SegmentTime, tailTmp)); err != nil {
		os.RemoveAll(tailTmp)
		return err
	}
	tailPlaylist, err := os.ReadFile(filepath.Join(tailTmp, "index.m3u8"))
	if err != nil {
		os.RemoveAll(tailTmp)
		return fmt.Errorf("stream: tail playlist: %w", err)
	}
	// Move tail artifacts under final/t/ and atomically rewrite the playlist
	// to the complete merge. From here the build is complete (ENDLIST).
	if err := moveTree(tailTmp, filepath.Join(final, "t")); err != nil {
		return fmt.Errorf("stream: move tail: %w", err)
	}
	merged := mergePlaylists(headPlaylist, tailPlaylist, "t/")
	return writeAtomic(final, filepath.Join(final, "index.m3u8"), merged)
}

// packHeadArgs builds the head-phase ffmpeg argument slice: the first
// HeadChunk seconds, stream-copy remux to fMP4-HLS (D-3), EVENT playlist with
// ENDLIST omitted (D-4: its absence marks a partial build). Pure.
func packHeadArgs(src string, head, segmentTime time.Duration, outDir string) []string {
	return []string{
		"-nostdin",
		"-i", src,
		"-t", strconv.FormatFloat(head.Seconds(), 'f', 3, 64),
		"-map", "0:v:0",
		"-map", "0:a",
		"-sn", "-dn",
		"-c", "copy",
		"-f", "hls",
		"-hls_time", strconv.FormatFloat(segmentTime.Seconds(), 'f', 3, 64),
		"-hls_playlist_type", "event",
		"-hls_flags", "omit_endlist",
		"-hls_segment_type", "fmp4",
		"-hls_fmp4_init_filename", "init.mp4",
		"-hls_segment_filename", filepath.Join(outDir, "seg-%05d.m4s"),
		filepath.Join(outDir, "index.m3u8"),
	}
}

// packTailArgs builds the tail-phase ffmpeg argument slice: the remainder from
// HeadChunk onward, identical remux flags so the artifact shape matches. Pure.
func packTailArgs(src string, head, segmentTime time.Duration, outDir string) []string {
	return []string{
		"-nostdin",
		"-ss", strconv.FormatFloat(head.Seconds(), 'f', 3, 64),
		"-i", src,
		"-map", "0:v:0",
		"-map", "0:a",
		"-sn", "-dn",
		"-c", "copy",
		"-f", "hls",
		"-hls_time", strconv.FormatFloat(segmentTime.Seconds(), 'f', 3, 64),
		"-hls_playlist_type", "event",
		"-hls_segment_type", "fmp4",
		"-hls_fmp4_init_filename", "init.mp4",
		"-hls_segment_filename", filepath.Join(outDir, "seg-%05d.m4s"),
		filepath.Join(outDir, "index.m3u8"),
	}
}

// runFFmpeg is THE ffmpeg exec site of the whole system (D-3 — the frame-
// grabber precedent): os/exec with an argument slice, never a shell, bounded
// by the caller's context plus PackTimeout (a hang guard; long legitimate runs
// renew the enrich lane's lease while this proceeds).
func (s *Service) runFFmpeg(ctx context.Context, args []string) error {
	if _, err := exec.LookPath(s.FFmpeg); err != nil {
		return fmt.Errorf("stream: ffmpeg not found: %w", err)
	}
	pctx, cancel := context.WithTimeout(ctx, s.PackTimeout)
	defer cancel()
	cmd := exec.CommandContext(pctx, s.FFmpeg, args...)
	if out, err := cmd.CombinedOutput(); err != nil {
		if ctx.Err() != nil {
			return ctx.Err()
		}
		if errors.Is(pctx.Err(), context.DeadlineExceeded) {
			return fmt.Errorf("stream: ffmpeg timed out after %s", s.PackTimeout)
		}
		return fmt.Errorf("stream: ffmpeg failed: %w: %s", err, truncate(out, 512))
	}
	return nil
}

// mergePlaylists merges the tail playlist's media entries into the head
// playlist, producing the complete byte-stable build playlist: the head's
// header + entries, an EXT-X-DISCONTINUITY (the tail is a separately
// initialized splice), the tail's EXT-X-MAP with its URI prefixed into t/,
// the tail's EXTINF/URI entries with segment URIs prefixed, and the closing
// ENDLIST. Pure: identical inputs yield byte-identical output (D-5).
func mergePlaylists(head, tail []byte, prefix string) []byte {
	var out []string
	for _, l := range strings.Split(string(head), "\n") {
		if strings.TrimSpace(l) == "#EXT-X-ENDLIST" {
			continue // defensive: the head playlist never carries one
		}
		if l != "" || len(out) > 0 {
			out = append(out, l)
		}
	}
	out = append(out, "#EXT-X-DISCONTINUITY")
	entries := false
	for _, l := range strings.Split(string(tail), "\n") {
		l = strings.TrimRight(l, "\r")
		switch {
		case strings.HasPrefix(l, "#EXT-X-MAP"):
			out = append(out, prefixURIAttribute(l, prefix))
		case strings.HasPrefix(l, "#EXTINF"):
			entries = true
			out = append(out, l)
		case strings.HasPrefix(l, "#"):
			// other tail tags (headers, ENDLIST) never merge
		case l == "":
		default:
			if entries {
				out = append(out, prefix+l)
			}
		}
	}
	out = append(out, "#EXT-X-ENDLIST")
	return []byte(strings.Join(out, "\n") + "\n")
}

// finalizeHead appends the closing ENDLIST to a head-only playlist (the
// whole-file-fits-in-the-head-chunk case). Pure.
func finalizeHead(head []byte) []byte {
	s := strings.TrimRight(string(head), "\n\r")
	if s == "" {
		return []byte("#EXTM3U\n#EXT-X-ENDLIST\n")
	}
	return []byte(s + "\n#EXT-X-ENDLIST\n")
}

// prefixURIAttribute rewrites the URI="..." attribute of an HLS tag (the
// tail's EXT-X-MAP) to point inside the tail prefix. Pure.
func prefixURIAttribute(tag, prefix string) string {
	i := strings.Index(tag, `URI="`)
	if i < 0 {
		return tag
	}
	rest := tag[i+len(`URI="`):]
	j := strings.Index(rest, `"`)
	if j < 0 {
		return tag
	}
	return tag[:i+len(`URI="`)] + prefix + rest[:j] + rest[j:]
}

// writeAtomic publishes b at dst (creating dir on demand) by writing a .tmp
// sibling in the same directory and renaming it into place (D-5: no partial
// file is ever served).
func writeAtomic(dir, dst string, b []byte) error {
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return fmt.Errorf("stream: create publish dir: %w", err)
	}
	tmp := dst + ".tmp"
	if err := os.WriteFile(tmp, b, 0o644); err != nil {
		return fmt.Errorf("stream: write %s: %w", filepath.Base(dst), err)
	}
	if err := os.Rename(tmp, dst); err != nil {
		os.Remove(tmp)
		return fmt.Errorf("stream: publish %s: %w", filepath.Base(dst), err)
	}
	return nil
}

// moveTree moves src's entries into dst (created on demand), then removes the
// empty src. Used to fold the tail phase's artifacts under the published
// build's t/ directory.
func moveTree(src, dst string) error {
	if err := os.MkdirAll(dst, 0o755); err != nil {
		return err
	}
	entries, err := os.ReadDir(src)
	if err != nil {
		return err
	}
	for _, e := range entries {
		if err := os.Rename(filepath.Join(src, e.Name()), filepath.Join(dst, e.Name())); err != nil {
			return err
		}
	}
	return os.Remove(src)
}

// probeSeconds extracts format.duration from a stored verbatim ffprobe map
// (seconds; 0 when absent or unparseable — the caller then assumes a long
// file). Matches the scanners' shape: duration rides as a JSON string.
func probeSeconds(ffprobe map[string]any) float64 {
	format, ok := ffprobe["format"].(map[string]any)
	if !ok {
		return 0
	}
	switch d := format["duration"].(type) {
	case string:
		if f, err := strconv.ParseFloat(strings.TrimSpace(d), 64); err == nil && f > 0 {
			return f
		}
	case float64:
		if d > 0 {
			return d
		}
	}
	return 0
}

// truncate caps captured ffmpeg output so an error message stays log-shaped.
func truncate(b []byte, n int) string {
	s := string(bytes.TrimSpace(b))
	if len(s) > n {
		s = s[:n]
	}
	return s
}
